export const ALL_CARDS: Card[] = rawCards.map((card, index) => {
  const teamColor = teamColors[card.team] || '#333';
  const teamLogoUrl = teamLogos[card.team];
  const coach = teamCoaches[card.team];
  
  // Calculate OVR based on stats
  // Formula: 66 + (PTS * 0.8) + (AST * 0.6) + (REB * 0.6)
  const baseOvr = Math.round(66 + (card.pts * 0.8) + (card.ast * 0.6) + (card.reb * 0.6));
  
  let ovr = baseOvr;
  const category = (card as any).category || 'Base';
  const rarity = card.rarity;

  // Apply Hierarchy Ranges (FIFA-style balancing)
  if (category === 'Finals MVP' || category === 'MVP' || card.id.startsWith('mvp')) {
    // MVP / Finals MVP: 95-99
    ovr = Math.max(95, Math.min(baseOvr, 99));
  } else if (category === 'All-Star MVP' || card.id.startsWith('as-mvp')) {
    // All-Star MVP: 92-94
    ovr = Math.max(92, Math.min(baseOvr, 94));
  } else if (category === '6th Man' || card.id.startsWith('6moy')) {
    // 6th Man: 80-84
    ovr = Math.max(80, Math.min(baseOvr, 84));
  } else if ((rarity as string) === 'legend' || card.id.startsWith('record')) {
    // Legends / Records: 92-96
    ovr = Math.max(92, Math.min(baseOvr, 96));
  } else if ((rarity as string) === 'dpoy' || card.id.startsWith('dpoy')) {
    // DPOY: 90-94
    ovr = Math.max(90, Math.min(baseOvr, 94));
  } else if ((rarity as string) === 'roty' || card.id.startsWith('roty')) {
    // ROTY: 86-90
    ovr = Math.max(86, Math.min(baseOvr, 90));
  } else if (card.id.startsWith('mip')) {
    // MIP: 85-92
    ovr = Math.max(85, Math.min(baseOvr, 92));
  } else if (category === 'Draft 2026' || card.id.startsWith('draft26')) {
    // Draft 2026: 78-92 based on projection
    const pickNum = parseInt(card.id.split('-')[1]) || 30;
    ovr = Math.round(92 - (pickNum * 0.4));
    ovr = Math.max(78, Math.min(ovr, 92));
    } else if (category === 'Scoring Champion' || card.id.startsWith('score')) {
    // Scoring Champion: 92-99 based on PPG
    ovr = Math.round(80 + (card.pts * 0.5));
    ovr = Math.max(90, Math.min(ovr, 99));
  } else if (category === 'Coach of the Year' || (rarity as string) === 'coy' || card.id.startsWith('coy')) {
    // Coach of the Year: 90-99 based on wins
    ovr = Math.round(75 + (card.pts * 0.4));
    ovr = Math.max(90, Math.min(ovr, 99));
  } else if (category === 'Hall of Fame' || (rarity as string) === 'hof' || card.id.startsWith('hof')) {
    // Hall of Fame: 94-99
    ovr = Math.max(94, Math.min(baseOvr, 99));
  } else if (category === 'Rising Star' || (rarity as string) === 'rising_star' || card.id.startsWith('rs-')) {
    // Rising Star: 84-90
    ovr = Math.max(84, Math.min(baseOvr, 90));
  } else if (category === 'All-NBA 1st Team' || (rarity as string) === 'allnba_1st' || card.id.startsWith('allnba-')) {
    // All-NBA 1st Team: 94-99
    ovr = Math.max(94, Math.min(baseOvr, 99));
  } else if (category === 'Arena' || card.id.startsWith('arena')) {
    // Arenas: 80-90 based on capacity and age
    const cap = card.pts;
    const year = card.reb;
    ovr = Math.round(80 + (cap / 21000) * 5 + (Math.max(0, (year - 1960) / 60)) * 5);
    ovr = Math.max(80, Math.min(ovr, 92));
  } else if (category === 'Logo' || card.id.startsWith('logo')) {
    // Logos: 85-99 based on wins and titles
    const titles = card.ast;
    const wins = card.pts;
    ovr = Math.round(85 + (wins / 64) * 10 + (titles / 18) * 4);
    ovr = Math.max(85, Math.min(ovr, 99));
  } else {
    // Base Cards
    switch (rarity as string) {
      case 'bench':
        ovr = Math.max(65, Math.min(baseOvr, 74));
        break;
      case 'starter':
        ovr = Math.max(75, Math.min(baseOvr, 83));
        break;
      case 'allstar':
        ovr = Math.max(84, Math.min(baseOvr, 88));
        break;
      case 'franchise':
        ovr = Math.max(89, Math.min(baseOvr, 91));
        break;
      case 'rookie':
        ovr = Math.max(70, Math.min(baseOvr, 79));
        break;
      default:
        ovr = Math.min(baseOvr, 99);
    }
  }
  
  return {
    ...card,
    number: index + 1,
    teamColor,
    teamLogoUrl,
    coach,
    rarity: (card as any).category === 'Coach' ? 'coach' : card.rarity,
    category: (card as any).category || 'Base',
    series: (card as any).category === 'Award' || (card as any).category === 'NBA Record' || (card as any).category === 'All-Star MVP' || (card as any).category === 'Finals MVP'
      ? (card.id.startsWith('mvp') ? 'Legendary MVP Series' : 
         card.id.startsWith('dpoy') ? 'DPOY Series' : 
         card.id.startsWith('roty') ? 'ROTY Series' :
         card.id.startsWith('mip') ? 'MIP Series' : 
         card.id.startsWith('record') ? 'NBA Record Series' :
         card.id.startsWith('as-mvp') ? 'All-Star MVP Series' :
         card.id.startsWith('fmvp') ? 'Finals MVP Series' :
         '6MOY Series') 
      : (card as any).category === 'Rookie' ? '2025 Rookie Class' : 
        (card as any).category === 'Draft 2026' ? '2026 Prospect Class' :
        (card as any).category === 'Scoring Champion' ? 'NBA Scoring Champions' :
        (card as any).category === 'Hall of Fame' ? 'NBA Hall of Fame' :
        (card as any).category === 'All-NBA 1st Team' ? 'All-NBA First Team Series' :
        (card as any).category === 'Coach of the Year' ? 'NBA Coach of the Year' :
        (card as any).category === 'Logo' ? 'NBA Team Logo Series' : 
        (card as any).category === 'Arena' ? 'NBA Arena Series' : undefined,
    subtitle: (card as any).category === 'Coach' 
      ? 'HEAD COACH' 
      : (card as any).category === 'Logo'
        ? 'NBA LOGO SERIES'
        : (card as any).category === 'Arena'
          ? 'OFFICIAL TEAM ARENA'
          : (card as any).category === 'Draft 2026'
            ? `PICK #${card.id.split('-')[1]} • 2026 PROSPECT`
            : (card as any).category === 'Scoring Champion'
              ? `${(card as any).year} SCORING CHAMPION`
              : (card as any).category === 'Hall of Fame'
                ? `CLASS OF ${(card as any).year} • HOF`
                : (card as any).category === 'Coach of the Year'
                  ? `${(card as any).year} COACH OF THE YEAR`
                  : (card as any).category === 'Award' || (card as any).category === 'NBA Record' || (card as any).category === 'All-Star MVP' || (card as any).category === 'Finals MVP'
        ? `${(card as any).year} ${
            card.id.startsWith('mvp') ? 'MVP' : 
            card.id.startsWith('dpoy') ? 'DPOY' : 
            card.id.startsWith('roty') ? 'ROTY' : 
            card.id.startsWith('mip') ? 'MIP' : 
            card.id.startsWith('record') ? 'NBA RECORD' :
            card.id.startsWith('as-mvp') ? 'ALL-STAR MVP' :
            card.id.startsWith('fmvp') ? 'FINALS MVP' :
            '6MOY'
          }` 
        : (card as any).category === 'Rookie'
          ? 'ROOKIE CLASS'
          : (card as any).category === 'Duo'
          ? 'DYNAMIC DUO'
          : (card as any).category === 'Moment'
            ? `${(card as any).year} ICONIC MOMENT`
            : (card as any).category === 'Dynasty'
              ? 'TEAM DYNASTY'
              : (card as any).category === 'X-Factor'
                ? 'IMPACT PLAYER'
                : (card as any).category === 'All-NBA 1st Team'
                  ? `${(card as any).year} ALL-NBA FIRST TEAM`
                  : `${card.rarity.toUpperCase()} EDITION`,
    stats: {
      points: card.pts,
      rebounds: card.reb,
      assists: card.ast,
      ovr: (card as any).category === 'Coach' ? (card as any).ovr || 90 : ovr,
    },
    description: card.quote,
  };
});

// Optimized pools for faster pack opening
export const CARDS_BY_RARITY = ALL_CARDS.reduce((acc, card) => {
  if (!acc[card.rarity]) acc[card.rarity] = [];
  acc[card.rarity].push(card);
  return acc;
}, {} as Record<Rarity, Card[]>);

export const CARDS_BY_SERIES = ALL_CARDS.reduce((acc, card) => {
  if (card.series) {
    if (!acc[card.series]) acc[card.series] = [];
    acc[card.series].push(card);
  }
  return acc;
}, {} as Record<string, Card[]>);
